{
  "title": "萌",
  "heteronyms": [
    {
      "bopomofo": "ㄇㄥˊ",
      "definitions": [
        {
          "def": "草木初生的芽。",
          "quote": [
            "《說文解字．艸部》：「萌，艸芽也。」",
            "唐．韓愈、劉師服、侯喜、軒轅彌明〈石鼎聯句〉：「秋瓜未落蒂，凍芋強抽萌。」"
          ],
          "type": "名"
        },
        {
          "def": "事物發生的開端或徵兆。",
          "quote": [
            "《韓非子．說林上》：「聖人見微以知萌，見端以知末。」",
            "漢．蔡邕〈對詔問灾異八事〉：「以杜漸防萌，則其救也。」"
          ],
          "type": "名"
        },
        {
          "example": [
            "如：「萌黎」、「萌隸」。"
          ],
          "def": "人民。",
          "link": [
            "通「氓」。"
          ],
          "type": "名"
        },
        {
          "def": "姓。如五代時蜀有萌慮。",
          "type": "名"
        },
        {
          "example": [
            "如：「萌芽」。"
          ],
          "def": "發芽。",
          "quote": [
            "《楚辭．王逸．九思．傷時》：「明風習習兮龢暖，百草萌兮華榮。」"
          ],
          "type": "動"
        },
        {
          "example": [
            "如：「故態復萌」。"
          ],
          "def": "發生。",
          "quote": [
            "《管子．牧民》：「惟有道者，能備患於未形也，故禍不萌。」",
            "《三國演義》第一回：「若萌異心，必獲惡報。」"
          ],
          "type": "動"
        }
      ],
      "pinyin": "méng",
      "bopomofo2": "méng"
    }
  ],
  "radical": "艸",
  "stroke_count": 12,
  "non_radical_stroke_count": 8
}
